# Find all occurrences of "What is your favorite novel?"
target_question = "What is your favorite novel?"
occurrences = []
for i, line in enumerate(lines):
    if line == f"user: {target_question}":
        occurrences.append(i)
        print(f"Found at line {i}: {repr(lines[i])}")
        if i+1 < len(lines):
            print(f"  Assistant response: {repr(lines[i+1])}")

print(f"\nTotal occurrences: {len(occurrences)}")

